        <div class="list-bar"><span class="small muted">Period</span>${d.periods.map(p => `<button class="btn sm ${f.from === p.from && f.to === p.to ? 'primary' : ''}" data-pd="${p.key}">${esc(p.label)}</button>`).join('')}</div>
