    // after an action the list stays on its page and at its scroll position
    const again = (x = {}) => { SL.y = window.scrollY; if (batch) { SL.bp = x.page || SL.bp || 1; } else Object.assign(SL.f, x); return pageSales(batch).then(() => window.scrollTo(0, SL.y)); };
