      const it = (i, sale, cur) => `<tr style="${cur ? 'background:#e6f4ea' : ''}"><td>#${i.id}</td><td>${esc(i.order_no || '')}</td><td>${esc(i.date || '')}</td><td>${esc(i.name || '')}</td><td>${esc(i.postcode || '')}</td><td>${esc(i.phone || '')}</td><td class="small">${esc(i.title || '')}</td><td class="num">${i.qty}</td><td class="num">${gbp(i.cost)}</td><td>${cur ? '<span class="chip done">used now</span>' : c.can_pick ? `<button class="btn sm primary" data-pick="${sale}:${i.id}">Use this one</button>` : ''}</td></tr>`;
