        <td><select data-pab="${r.task}">${d.bins.map(b => `<option value="${b.id}" ${r.to && +r.to.bin === +b.id ? 'selected' : ''}>${esc(b.name)}</option>`).join('')}</select>${r.to ? `<div class="small muted">Suggested: ${esc(r.to.name)} (${esc(r.to.why)})</div>` : ''}</td>
